<?php if(!defined('ABSPATH'))exit;if($role!=='admin'){echo '<p>Access denied.</p>';return;} global $wpdb;$t=$wpdb->prefix;$rows=$wpdb->get_results("SELECT e.*,u.display_name FROM {$t}rp_expenses e LEFT JOIN {$wpdb->users} u ON u.ID=e.created_by ORDER BY e.expense_date DESC,e.id DESC LIMIT 100");$total=0;foreach($rows as $r)$total+=(float)$r->amount;?>
<h1 class="page-title">Expenses</h1><div class="p-card" style="background:#111827;color:#fff"><strong>Total recent expenses</strong><div style="font-size:1.7rem;margin-top:4px">Rs. <?php echo number_format($total,2);?></div></div>
<div class="p-card"><h3 class="p-card-title mb-12">Record Expense</h3><form method="post"><?php wp_nonce_field('rp_expense_action');?><input type="hidden" name="rp_expense_action" value="add"><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px"><input class="form-input" type="date" name="expense_date" value="<?php echo esc_attr(current_time('Y-m-d'));?>"><input class="form-input" name="category" placeholder="Category (Rent, Supplies, Utilities)"><input class="form-input" name="description" placeholder="Description"><input class="form-input" name="amount" type="number" step="0.01" min="0" required placeholder="Amount"><select class="form-select" name="payment_method"><option>cash</option><option>eSewa</option><option>Khalti</option><option>FonePay/QR</option><option>Card</option><option>Credit</option></select><input class="form-input" name="reference" placeholder="Reference"></div><button class="btn btn-primary" type="submit">Save Expense</button></form></div>
<div class="p-card"><h3 class="p-card-title mb-12">Recent Expenses</h3><?php foreach($rows as $r):?><div class="order-item"><span class="order-num"><?php echo esc_html(wp_date('d M',strtotime($r->expense_date)));?></span><div class="order-meta"><strong><?php echo esc_html($r->category);?></strong><span class="text-sm text-muted"><?php echo esc_html($r->description);?> • <?php echo esc_html($r->payment_method);?></span></div><strong>Rs. <?php echo number_format((float)$r->amount,2);?></strong></div><?php endforeach;?></div>